-- 1010: Injection molding deflashing calculator -- the parting line length over the manual flash trimming rate.
--
-- GENERATED by scripts/generate-plastic-molding-calculators-migration.ts from
-- src/modules/bom-items/costing/plastic-molding/calculators/plastic-molding-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Deflashing is routed for an injection-molded part with a complex parting line, but it was not costed: the engine knew of no rate. The reference stages
-- cmManualFlashTrimmingRate (75, Length/Time) for compression molding, and the CAD engine measures the parting line length. This calculator times
-- the trim as length / rate (formula registry F-24, ASSUMED: the rate is borrowed from compression molding and read as mm/s). A helper: no catalog
-- operation maps to it; the injection engine runs it for the routed deflashing step.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Injection Molding - Deflashing
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Deflashing$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Injection Molding - Deflashing$q$, 'process', 'single', false, true, true, $q$Deflashing time = the parting line length / the manual flash trimming rate (formula registry F-24, ASSUMED). The parting line length is the CAD measurement of the PartingLine feature. The rate is the reference variable cmManualFlashTrimmingRate (75), staged for compression molding (Compression Molding:Manual Flash Trimming//PartingLine) and borrowed for injection molding, which has no staged rate. The reference types the rate only as Length/Time; it is read as mm/s, the unit that fits the reference's other Length/Time rates (grindSpeed 381, defaultAviInspectionSpeed 110, cmAirHoseCleaningRateLinear 100) and a manual trim (mm/min would put a 785 mm parting line at over 10 minutes). Routed when the parting line is complex (routing engine); internal cutouts and flash thickness are not modelled. A missing length or rate makes the line a named gap, never a default.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Deflashing time = the parting line length / the manual flash trimming rate (formula registry F-24, ASSUMED). The parting line length is the CAD measurement of the PartingLine feature. The rate is the reference variable cmManualFlashTrimmingRate (75), staged for compression molding (Compression Molding:Manual Flash Trimming//PartingLine) and borrowed for injection molding, which has no staged rate. The reference types the rate only as Length/Time; it is read as mm/s, the unit that fits the reference's other Length/Time rates (grindSpeed 381, defaultAviInspectionSpeed 110, cmAirHoseCleaningRateLinear 100) and a manual trim (mm/min would put a 785 mm parting line at over 10 minutes). Routed when the parting line is complex (routing engine); internal cutouts and flash thickness are not modelled. A missing length or rate makes the line a named gap, never a default.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Parting Line Length$q$, $q$Parting Line Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Manual Flash Trimming Rate$q$, $q$Manual Flash Trimming Rate (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$floor({Parting Line Length} / {Manual Flash Trimming Rate} * 100 + 0.5) / 100$q$, 3, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Injection Molding - Deflashing$q$, 3, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Plastic Molding$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1010: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
